// === Tab: mySketch ===
// For the #WCCChallenge, theme: "De Stijl."
// De Stijl typeface published by Darryl Driyarto Han under a Creative Commons License 4.0: 
// https://www.behance.net/gallery/1495561/De-Stijl-Typo-Poster

var letters = [];
var imgs = [];
var alpha = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';
var months = ['JAN', 'FEB', 'MAR', 'APR', 'MAY', 'JUN', 'JUL', 'AUG', 'SEP', 'OCT', 'NOV', 'DEC'];
var days = ['SUN', 'MON', 'TUE', 'WED', 'THU', 'FRI', 'SAT'];
var lastsecond = 0;
var ticking = true;
var tilting = true;
var tiltcount = 3;
var shear;
var mode = 2;

function preload() {
	page = loadImage('file:///Users/unclerm/Vibe Coding/4K MV Visual Integration Editor/assets_cache/letters.jpg');
}

function setup() {
	createCanvas(windowHeight, windowHeight);
	imageMode(CENTER);
	makeLetters();
}

function makeLetters() {
	let lx = 5;
	let lrow = -3;
	let lcol = -3;
	let ly = 90.5 + lrow * 181;
	for (let row = 0; row < 7; row++) {
		let y = 54 + row * 226.5;
		for (let col = 0; col < 6; col++) {
			lx = 61 + lcol * 122;
			if ((row == 4 && col > 1) || (row == 6 && col > 3)) continue;
			let x = 111 + col * 170;
			let img = page.get(x, y, 121, 179);
			letters.push(new Letter(img, lx, ly));
			imgs.push(img);
			lcol += 1;
			if (lcol == 3) {
				lcol = -3;
				lrow += 1;
				ly = 90 + lrow * 181;
			}
		}
	}
}

function draw() {
	if (lastsecond == second() || !ticking) return;
	if (tilting) tiltcount += 1;
	shear = sin(tiltcount / 4) * PI / 12;
	lastsecond = second();
	buildDate()
	background(255);
	translate(width / 2, height / 2);
	rectMode(CENTER);
	scale(0.5 * (height / 628));
	noStroke();
	fill(0);
	rect(10, 20, 820, 1160);
	filter(BLUR, 8);
	translate(width / 2, height / 2);
	scale(0.5 * (height / 628));
	fill(240);
	stroke(60);
	strokeWeight(20);
	rect(0, 0, 800, 1150);
	stroke(0, 50);
	strokeWeight(12);
	rect(0, 0, 790, 1140);
	noStroke();
	for (let l of letters) {
		l.show();
	}
}

function buildDate() {
	let mon = months[month() - 1];
	let d = new Date().getDay();
	let dayname = days[d];
	let hr = hour();
	if (hr > 12) hr -= 12;
	letters[0].img = imgs[3];
	letters[1].img = imgs[0];
	letters[2].img = imgs[24];
	letters[3].img = imgs[alpha.indexOf(dayname.substring(0, 1))];
	letters[4].img = imgs[alpha.indexOf(dayname.substring(1, 2))];
	letters[5].img = imgs[alpha.indexOf(dayname.substring(2, 3))];
	letters[6].img = imgs[12];
	letters[7].img = imgs[14];
	letters[8].img = imgs[13];
	letters[9].img = imgs[alpha.indexOf(mon.substring(0, 1))];
	letters[10].img = imgs[alpha.indexOf(mon.substring(1, 2))];
	letters[11].img = imgs[alpha.indexOf(mon.substring(2, 3))];
	letters[12].img = imgs[3];
	letters[13].img = imgs[0];
	letters[14].img = imgs[19];
	letters[15].img = imgs[4];
	letters[16].img = imgs[26 + floor(day() / 10) % 10];
	letters[17].img = imgs[26 + day() % 10];
	letters[18].img = imgs[24];
	letters[19].img = imgs[17];
	letters[20].img = imgs[26 + floor(year() / 1000) % 10];
	letters[21].img = imgs[26 + floor(year() / 100) % 10];
	letters[22].img = imgs[26 + floor(year() / 10) % 10];
	letters[23].img = imgs[26 + year() % 10];
	letters[24].img = imgs[26 + floor(hr / 10)];
	letters[25].img = imgs[26 + hr % 10];
	letters[26].img = imgs[26 + floor(minute() / 10)];
	letters[27].img = imgs[26 + minute() % 10];
	letters[28].img = imgs[26 + floor(second() / 10)];
	letters[29].img = imgs[26 + second() % 10];
	letters[30].img = imgs[14];
	letters[31].img = imgs[2];
	letters[32].img = imgs[11];
	letters[33].img = imgs[14];
	letters[34].img = imgs[2];
	letters[35].img = imgs[10];
}

class Letter {
	constructor(img, x, y) {
		this.img = img;
		this.oimg = img;
		this.pos = createVector(x, y);
	}
	show() {
		push();
		translate(this.pos);
		shearY(shear);
		image(this.img, 0, 0);
		pop();
	}
}

function mousePressed() {
	mode = (mode + 1) % 3;
	switch (mode) {
		case 0:
			ticking = true;
			tilting = false;
			break
		case 1:
			ticking = false;
			tilting = false;
			break
		case 2:
			ticking = true;
			tilting = true;
			break
	}
}
